// Shared rules are published explicitly by an administrator; edits remain local until then.
async function loadSharedRules(force=false){
 try{const res=await fetch('/api/rules');if(!res.ok)throw Error();const data=await res.json();if(!validateRuleFile(data.rules))throw Error();
  if(isAdmin&&sharedRulesState.dirty&&!force)return;if(isAdmin&&!force&&data.revision===0&&JSON.stringify(rules)!==JSON.stringify(E.defaults)){sharedRulesState={revision:0,dirty:true,connected:true};render();return;}
  rules=data.rules;sharedRulesState={revision:data.revision,dirty:false,connected:true};if(isAdmin)try{localStorage.setItem('ip-rules-v1',JSON.stringify(rules))}catch{}
  invalidate();render();
 }catch{sharedRulesState.connected=false;if(state.page==='rules')render()}
}
function adminAction(title,action){
 modal(`<h2>${esc(title)}</h2><p>请输入管理员口令。口令仅用于本次操作，不保存。</p><input id="admin-token" type="password" autocomplete="off" aria-label="管理员口令"><p id="admin-error" role="alert"></p><button class="primary" id="admin-submit">确认</button>`);
 $('#admin-submit').onclick=async()=>{const token=$('#admin-token').value;$('#admin-token').value='';$('#admin-submit').disabled=true;try{await action(token);$('#modal').close()}catch(e){$('#admin-error').textContent=e.message;$('#admin-submit').disabled=false}};
}
function publishRules(){adminAction('发布共享规则',async token=>{const res=await fetch('/api/rules',{method:'PUT',headers:{'Content-Type':'application/json','X-Intel-Admin-Token':token},body:JSON.stringify({revision:sharedRulesState.revision,rules})});const data=await res.json();if(!res.ok)throw Error(data.error?.message||'发布失败');sharedRulesState={revision:data.revision,connected:true,dirty:false};render();toast('共享规则已发布，其他访问者刷新后可读取')})}
function validateRuleFile(list){return Array.isArray(list)&&list.length<=100&&list.every(x=>x&&typeof x.id==='string'&&x.id.length<=100&&typeof x.title==='string'&&x.title.trim()&&typeof x.note==='string'&&typeof x.enabled==='boolean'&&['高','中','低'].includes(x.level)&&['全部','FDE 驻场开发','AI 大模型','委托研发','技术许可'].includes(x.scenario)&&Array.isArray(x.keywords)&&x.keywords.every(k=>typeof k==='string')&&E.sources.some(s=>s.id===x.source))}
function saveJSON(value,name){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function deleteRule(id){const rule=rules.find(x=>x.id===id);if(!rule)return;modal(`<h2>删除规则</h2><p>确认从当前草稿删除“${esc(rule.title)}”？发布后其他访问者才会看到变更。</p><button class="primary" id="confirm-delete-rule">确认删除</button>`);$('#confirm-delete-rule').onclick=()=>{rules=rules.filter(x=>x.id!==id);persist();invalidate();$('#modal').close();render()}}
async function showSystem(){
 modal('<h2>系统状态</h2><p>正在检查连接…</p>');
 try{const s=await apiRequest('/api/system');modal(`<h2>知界系统状态</h2><p>版本：${esc(s.version)}</p><p>大模型：${s.modelConfigured?'已配置 '+esc(s.model)+'，实际调用需通过审查或采集验证':'未配置'}</p><p>管理员口令：${s.adminConfigured?'已配置':'未配置'}</p><p>每日采集：${s.schedule?.enabled?'每天08:00（北京时间），实例运行时执行':'未启用'}</p><p>数据保存：${esc(s.storage)}。${s.persistentStorageConfirmed?'管理员已声明挂载持久化存储，仍需验证挂载效果':'尚未确认持久化，重新部署可能丢失情报和共享规则'}</p><p>${esc(s.contractStorage)}</p><p>采集范围：${esc(s.sourceCoverage)}</p><p>系统按单实例部署。采集状态中的错误需处理；配置成功不等于来源或模型调用成功。</p><button class="secondary" id="export-backup">导出情报与规则备份</button><label class="secondary">恢复备份<input id="restore-backup" type="file" accept=".json" hidden></label>`);$('#restore-backup').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>900000)throw Error('备份超过900KB，请分批处理');const value=JSON.parse(await f.text());adminAction('确认覆盖当前规则与情报？',async token=>{const res=await fetch('/api/restore',{method:'POST',headers:{'Content-Type':'application/json','X-Intel-Admin-Token':token},body:JSON.stringify(value)});const data=await res.json();if(!res.ok)throw Error(data.error?.message||'恢复失败');await loadSharedRules(true);await loadIntel();toast('规则与情报已恢复')})}catch(e){toast(e.message)}};$('#export-backup').onclick=()=>adminAction('导出系统备份',async token=>{const res=await fetch('/api/backup',{headers:{'X-Intel-Admin-Token':token}});const data=await res.json();if(!res.ok)throw Error(data.error?.message||'导出失败');saveJSON(data,'知界-系统备份.json')})}
 catch{modal('<h2>无法连接后台</h2><p>请使用腾讯云站点地址打开知界，并确认服务版本正常。GitHub Pages 静态页面无法运行采集及模型接口。</p>')}
}
let draftingBusy=false,draftResult=null;
function showDraft(){modal(`<h2>起草知识产权条款</h2><p>立场：${esc(state.role)} · 合作场景：${esc(state.scenario)}</p><p>说明合作内容、已有成果、交付形式、数据用途和希望保留的权利。缺少的事实会标记为待补充。</p><textarea id="draft-requirements" maxlength="12000" aria-label="起草要求" placeholder="请描述实际合作需求，至少5个字"></textarea><p id="draft-error" role="alert"></p><button class="primary" id="draft-submit">生成条款</button><div id="draft-output"></div>`);$('#draft-submit').onclick=async()=>{if(draftingBusy)return;const requirements=$('#draft-requirements').value;if(requirements.trim().length<5){$('#draft-error').textContent='请至少填写5个字的合作需求';return}draftingBusy=true;$('#draft-submit').disabled=true;$('#draft-error').textContent='正在起草，通常需要几十秒…';try{draftResult=await apiRequest('/api/draft',{requirements,role:state.role,scenario:state.scenario,rules});$('#draft-error').textContent='已生成，待法务复核';$('#draft-output').innerHTML=`<div class="quote draft">${esc(draftResult.answer)}</div><p>${draftResult.sourceIds.map(id=>`<button class="link" data-draft-source="${esc(id)}">查看依据：${esc(E.sources.find(x=>x.id===id)?.title||id)}</button>`).join('')||'没有可引用的匹配法律依据，请人工补充核查。'}</p><button class="secondary" id="export-draft">导出条款 TXT</button>`;document.querySelectorAll('[data-draft-source]').forEach(b=>b.onclick=()=>source(b.dataset.draftSource));$('#export-draft').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([draftResult.answer],{type:'text/plain;charset=utf-8'}));a.href=url;a.download='知界-知识产权条款.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}catch(e){$('#draft-error').textContent=e.name==='TimeoutError'?'起草超时，请稍后重试。':e.message}finally{draftingBusy=false;$('#draft-submit').disabled=false}}}
function bindSystem(){
 if($('#system-status'))$('#system-status').onclick=showSystem;
 if($('#draft-contract')){$('#draft-contract').onclick=showDraft;$('#draft-contract').disabled=!backendState.aiConfigured||backendState.busy}
 if($('#publish-rules'))$('#publish-rules').onclick=publishRules;
 if($('#reload-rules'))$('#reload-rules').onclick=()=>{if(sharedRulesState.dirty){modal('<h2>重新读取共享规则？</h2><p>将丢弃当前尚未发布的修改。</p><button class="primary" id="reload-confirm">确认读取</button>');$('#reload-confirm').onclick=()=>{$('#modal').close();loadSharedRules(true)}}else loadSharedRules(true)};
 if($('#export-rules'))$('#export-rules').onclick=()=>saveJSON({rules},'知界-审查规则.json');
 if($('#import-rules'))$('#import-rules').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>200000)throw Error('规则文件过大');const data=JSON.parse(await f.text());if(!validateRuleFile(data.rules))throw Error('规则文件格式不正确');rules=data.rules;persist();invalidate();render();toast('已导入规则草稿，请复核后发布')}catch(e){toast(e.message)}};
 document.querySelectorAll('[data-delete-rule]').forEach(b=>b.onclick=()=>deleteRule(b.dataset.deleteRule));
}
loadSharedRules();

function showIntelSettings(){modal(`<h2>自动采集设置</h2><p>按北京时间执行；需后台实例保持运行。设置保存在数据目录，重建容器后是否保留取决于持久化挂载。</p><label>自动采集 <input type="checkbox" id="auto-enabled" ${intelTasks.enabled?'checked':''}></label><p>每日执行小时（0–23）</p><input id="auto-hour" type="number" min="0" max="23" value="${intelTasks.hour??8}"><p>每轮最多采集文章数（1–30）</p><input id="auto-max" type="number" min="1" max="30" value="${intelTasks.maxArticles??8}"><p><label><input type="checkbox" id="auto-ai" ${intelTasks.aiEnabled?'checked':''}> 可选：使用 AI 补充摘要</label></p><p>默认只采集官方摘录，无需模型密钥；AI 认证失败也会保留已采集资讯。</p><p>管理员口令</p><input type="password" autocomplete="off" id="auto-token"><p id="auto-error" role="alert"></p><button class="primary" id="save-auto">保存设置</button>`);$('#save-auto').onclick=async()=>{const payload={aiEnabled:$('#auto-ai').checked,enabled:$('#auto-enabled').checked,hour:Number($('#auto-hour').value),maxArticles:Number($('#auto-max').value)},token=$('#auto-token').value;$('#auto-token').value='';$('#save-auto').disabled=true;try{const res=await fetch('/api/intel/settings',{method:'PUT',headers:{'Content-Type':'application/json','X-Intel-Admin-Token':token},body:JSON.stringify(payload)});const data=await res.json();if(!res.ok)throw Error(data.error?.message||'保存失败');intelTasks=data;$('#modal').close();render();toast('自动采集设置已保存')}catch(e){$('#auto-error').textContent=e.message;$('#save-auto').disabled=false}}}

bindSystem();
